// Recent headlines for a listed company of the Investment category (26 Nov 2026): Yahoo Finance's public RSS headline
// feed, read on demand by the company pages and cached for 30 minutes in the Workers Cache API. No D1 writes, no cron.
//
// Safety: the caller names a listed company by its Google Finance symbol; only symbols of the reviewed allowlist
// (./symbols.js, generated by tools/export-investment.mjs from the public Investment snapshot) are fetched, and the
// upstream URL is built here from the mapped Yahoo symbol, never from caller input. One upstream request per cache miss,
// with a timeout, no redirects and a size limit; a refusal (such as 429) is cached briefly and never retried here.
// Only the headline, its link, its date and the link's domain are returned: no summaries or article text.

import { NEWS_SYMBOLS } from './symbols.js';

export const NEWS_TTL_SECONDS = 1800;
const ERROR_TTL_SECONDS = 300;
export const NEWS_MAX_ITEMS = 10;
const MAX_BYTES = 512 * 1024;
const TIMEOUT_MS = 6000;
export const NEWS_USER_AGENT = 'WhyHumanoid/1.0 (+https://whyhumanoid.com)';
const CACHE_ORIGIN = 'https://news-cache.whyhumanoid.invalid';

export const newsUrl = (yahoo) => `https://feeds.finance.yahoo.com/rss/2.0/headline?s=${encodeURIComponent(yahoo)}&region=US&lang=en-US`;

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };
function decode(s) {
  return String(s ?? '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<[^>]*>/g, '')
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => safeChar(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => safeChar(Number(d)))
    .replace(/&([a-z]+);/gi, (m, n) => ENTITIES[n.toLowerCase()] ?? m)
    .replace(/\s+/g, ' ')
    .trim();
}
function safeChar(n) {
  try { return n > 31 && n < 0x110000 ? String.fromCodePoint(n) : ' '; } catch { return ' '; }
}
const tag = (xml, name) => xml.match(new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`, 'i'))?.[1] ?? null;

// Headlines of an RSS document: https links only, newest first (the feed's order is not trusted), duplicates removed,
// at most NEWS_MAX_ITEMS. Undated items go last.
export function parseHeadlines(xml) {
  const items = [];
  const seen = new Set();
  for (const m of String(xml).matchAll(/<item\b[^>]*>([\s\S]*?)<\/item>/gi)) {
    const title = decode(tag(m[1], 'title')).slice(0, 300);
    let url = decode(tag(m[1], 'link'));
    let parsed = null;
    try { parsed = new URL(url); } catch { parsed = null; }
    if (!title || !parsed || parsed.protocol !== 'https:' || parsed.username || parsed.password) continue;
    url = parsed.href;
    const time = Date.parse(decode(tag(m[1], 'pubDate')));
    if (seen.has(url) || seen.has(title.toLowerCase())) continue;
    seen.add(url);
    seen.add(title.toLowerCase());
    items.push({ title, url, domain: parsed.hostname.replace(/^www\./, ''), published: Number.isFinite(time) ? new Date(time).toISOString() : null });
  }
  items.sort((a, b) => (b.published ?? '').localeCompare(a.published ?? ''));
  return items.slice(0, NEWS_MAX_ITEMS);
}

// Reads the body up to MAX_BYTES before the deadline; a stalled or endless body is cancelled, never awaited forever.
async function readCapped(response, deadline) {
  const reader = response.body?.getReader();
  if (!reader) return '';
  const chunks = [];
  let size = 0;
  for (;;) {
    const left = deadline - Date.now();
    let timer;
    const timeout = new Promise((_, reject) => { timer = setTimeout(() => reject(Object.assign(new Error('timeout'), { name: 'AbortError' })), Math.max(0, left)); });
    let step;
    try { step = await Promise.race([reader.read(), timeout]); } catch (e) { reader.cancel().catch(() => {}); throw e; } finally { clearTimeout(timer); }
    const { done, value } = step;
    if (done) break;
    size += value.byteLength;
    if (size > MAX_BYTES) { await reader.cancel(); throw new Error('feed_too_large'); }
    chunks.push(value);
  }
  const all = new Uint8Array(size);
  let at = 0;
  for (const c of chunks) { all.set(c, at); at += c.byteLength; }
  return new TextDecoder().decode(all);
}

// The public result for one security key. fetchImpl and cache are injected (Workers: fetch and caches.default).
export async function companyNews(key, { fetchImpl, cache = null, now = Date.now(), timeoutMs = TIMEOUT_MS }) {
  const entry = NEWS_SYMBOLS[key];
  if (!entry) return { status: 404, body: { error: 'unknown_security' } };
  const cacheKey = new Request(`${CACHE_ORIGIN}/${encodeURIComponent(entry.yahoo)}`);
  if (cache) {
    const hit = await cache.match(cacheKey).catch(() => null);
    if (hit) return { status: 200, body: await hit.json(), cached: true };
  }
  const base = { security: key, company: entry.name, yahoo_symbol: entry.yahoo, source: 'Yahoo Finance RSS headline feed', source_url: `https://finance.yahoo.com/quote/${encodeURIComponent(entry.yahoo)}/news/`, fetched_at: new Date(now).toISOString() };
  let body;
  let ttl = NEWS_TTL_SECONDS;
  try {
    // One deadline for the whole exchange: connection, headers and the complete body.
    const deadline = Date.now() + timeoutMs;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await fetchImpl(newsUrl(entry.yahoo), { headers: { 'user-agent': NEWS_USER_AGENT, accept: 'application/rss+xml, application/xml;q=0.9, text/xml;q=0.8' }, redirect: 'manual', signal: controller.signal });
      if (res.status !== 200) {
        res.body?.cancel?.().catch(() => {});
        body = { ...base, status: 'unavailable', reason: res.status === 429 ? 'rate_limited' : `upstream_${res.status}`, items: [] };
        ttl = ERROR_TTL_SECONDS;
      } else {
        const items = parseHeadlines(await readCapped(res, deadline));
        body = { ...base, status: items.length ? 'ok' : 'empty', items };
      }
    } finally { clearTimeout(timer); }
  } catch (e) {
    body = { ...base, status: 'unavailable', reason: e?.name === 'AbortError' ? 'timeout' : 'fetch_failed', items: [] };
    ttl = ERROR_TTL_SECONDS;
  }
  if (cache) {
    const stored = new Response(JSON.stringify(body), { headers: { 'content-type': 'application/json', 'cache-control': `public, max-age=${ttl}` } });
    await cache.put(cacheKey, stored).catch(() => {});
  }
  return { status: 200, body, ttl };
}
